// Akeneo Community no tiene webhooks: los eventos son de Enterprise.
// Por eso este flujo consulta por fecha de modificación en vez de esperar
// que Akeneo avise. El margen evita perder escrituras concurrentes.
const estado = $getWorkflowStaticData('global');
const margen = 5 * 60 * 1000;
const desde = estado.ultimoSondeo
  ? new Date(new Date(estado.ultimoSondeo).getTime() - margen)
  : new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

// Akeneo exige 'yyyy-MM-dd HH:mm:ss' en el filtro `updated`; con ISO 8601
// responde 400 sin explicar el motivo.
const formato = desde.toISOString().slice(0, 19).replace('T', ' ');
const busqueda = { updated: [{ operator: '>', value: formato }] };

return [{ json: { desde: formato, search: JSON.stringify(busqueda) } }];

// Traduce el producto de Akeneo al contrato que ya espera el conector de Medusa
// (apps/backend/src/api/admin/akeneo/webhook).
//
// El orden importa: el conector marca el producto como `retrying` si su autoría
// todavía no existe como categoría en Medusa. Por eso los eventos de autoría van
// primero en el mismo lote — la ruta los procesa en secuencia.
//
// Akeneo Community no tiene Reference Entities, así que la autoría se deriva de
// las opciones del atributo `onix_author` en vez de una entidad de referencia.
const crypto = require('crypto');

const productos = $('Productos modificados').first().json._embedded?.items ?? [];
if (!productos.length) {
  return [{ json: { vacio: true, eventos: 0 } }];
}

const locale = $env.AKENEO_LOCALE || 'es_ES';
const primerValor = (valores, atributo) => {
  const lista = valores?.[atributo];
  if (!Array.isArray(lista) || !lista.length) return null;
  const exacto = lista.find((v) => v.locale === locale);
  return (exacto ?? lista[0]).data ?? null;
};

const etiquetaAutor = new Map();
for (const opcion of $('Opciones de autoría').first().json._embedded?.items ?? []) {
  etiquetaAutor.set(opcion.code, opcion.labels?.[locale] ?? opcion.code);
}

const referenciados = new Set();
for (const producto of productos) {
  for (const codigo of producto.values?.onix_author?.[0]?.data ?? []) referenciados.add(codigo);
}

const eventosAutoria = [...referenciados].map((codigo) => ({
  event_id: `autor-${codigo}`,
  event_type: 'reference_entity_record.updated',
  // El conector lee `labels.es`; se emiten ambas claves para no depender de eso.
  data: { resource: { code: codigo, labels: { es: etiquetaAutor.get(codigo) ?? codigo, [locale]: etiquetaAutor.get(codigo) ?? codigo } } }
}));

const eventosProducto = productos.map((producto, indice) => {
  const valores = producto.values ?? {};
  return {
    event_id: `${producto.identifier}-${producto.updated ?? indice}`,
    event_type: producto.enabled ? 'product.updated' : 'product.removed',
    data: {
      resource: {
        identifier: producto.identifier,
        enabled: Boolean(producto.enabled),
        family: producto.family,
        categories: producto.categories ?? [],
        values: {
          label: [{ data: primerValor(valores, 'onix_title') ?? producto.identifier }],
          description: [{ data: primerValor(valores, 'onix_description') ?? '' }],
          author: (valores.onix_author?.[0]?.data ?? []).map((codigo) => ({ data: codigo }))
        }
      }
    }
  };
});

const events = [...eventosAutoria, ...eventosProducto];
const payload = JSON.stringify({ events });
const firma = crypto.createHmac('sha256', $env.AKENEO_WEBHOOK_SECRET).update(payload, 'utf8').digest('hex');

return [{ json: { vacio: false, eventos: events.length, autoria: eventosAutoria.length, payload, firma } }];

// La marca solo avanza si Medusa aceptó el lote completo.
const estado = $getWorkflowStaticData('global');
const codigo = $json.statusCode;
const cuerpo = $json.body ?? {};
const resultados = cuerpo.outcomes ?? cuerpo.events ?? cuerpo.results ?? [];
const fallidos = resultados.filter((r) => r.status === 'failed');

if (codigo >= 200 && codigo < 300 && fallidos.length === 0) {
  estado.ultimoSondeo = new Date().toISOString();
}

return [{ json: {
  codigo,
  aplicados: resultados.filter((r) => r.status === 'applied').length,
  reintentando: resultados.filter((r) => r.status === 'retrying').length,
  fallidos: fallidos.length,
  detalle: fallidos.slice(0, 5),
  marcaGuardada: estado.ultimoSondeo ?? null
} }];

// Sin cambios en la ventana: se avanza la marca igualmente para no
// reconsultar siempre el mismo rango vacío.
const estado = $getWorkflowStaticData('global');
estado.ultimoSondeo = new Date().toISOString();
return [{ json: { sinCambios: true, marcaGuardada: estado.ultimoSondeo } }];
